export function createCache({ ttlMs, capacity, clock = () => Date.now() }) {
  const entries = new Map() // key -> { value, expiresAt, lastUsed }, least-recently-used first
  return {
    get(key) {
      const entry = entries.get(key)
      if (entry === undefined) return undefined
      const now = clock()
      if (now > entry.expiresAt) {
        // TTL has passed: treat as a miss and drop the entry.
        entries.delete(key)
        return undefined
      }
      entry.lastUsed = now
      // Re-insert so this key counts as the most recently used.
      entries.delete(key)
      entries.set(key, entry)
      return entry.value
    },
    set(key, value) {
      const now = clock()
      if (entries.has(key)) {
        // Re-insert below so the key counts as the most recently used.
        entries.delete(key)
      } else if (entries.size >= capacity) {
        // Evict the least-recently-used entry (first in insertion order).
        entries.delete(entries.keys().next().value)
      }
      entries.set(key, { value, expiresAt: now + ttlMs, lastUsed: now })
    },

